// ---------- Derived views (pure functions, shared by UI and tests) ----------
export const netOf = rows => rows.length ? Math.round((rows.filter(r => r.sentiment === 'Positive').length - rows.filter(r => r.sentiment === 'Negative').length) / rows.length * 100) : 0;
export const splitOf = rows => SENTIMENTS.map(s => rows.filter(r => r.sentiment === s).length);
export const quarterOf = iso => { const y = +iso.slice(0, 4), m = +iso.slice(5, 7); return `${y} Q${Math.floor((m - 1) / 3) + 1}`; };
export const QUARTERS = Object.freeze(['2025 Q1', '2025 Q2', '2025 Q3', '2025 Q4', '2026 Q1', '2026 Q2', '2026 Q3']);

export function groupBy(rows, key) {
  const map = new Map();
  for (const r of rows) for (const k of [].concat(typeof key === 'function' ? key(r) : r[key])) { if (!map.has(k)) map.set(k, []); map.get(k).push(r); }
  return map;
}
export function filterStatements(rows, f = {}) {
  const q = (f.query || '').trim().toLowerCase();
  return rows.filter(r => (!f.specialty || r.specialty === f.specialty) && (!f.theme || r.themes.includes(f.theme)) && (!f.channel || r.channel === f.channel) && (!f.sentiment || r.sentiment === f.sentiment) && (!f.period || r.date.startsWith(f.period)) && (!q || `${r.who} ${r.role} ${r.text} ${r.source} ${r.specialty}`.toLowerCase().includes(q)));
}
export function themeShift(rows) {
  const a = rows.filter(r => r.date.startsWith('2025')), b = rows.filter(r => r.date.startsWith('2026'));
  const share = (set, t) => set.length ? set.filter(r => r.themes.includes(t)).length / set.length * 100 : 0;
  return THEMES.map(({ name }) => ({ name, y2025: share(a, name), y2026: share(b, name), n2025: a.filter(r => r.themes.includes(name)).length, n2026: b.filter(r => r.themes.includes(name)).length, delta: Math.round(share(b, name) - share(a, name)) }));
}

